import { Semaphore } from 'async-mutex';
class ServiceClient {
  private orderSem = new Semaphore(10);
  private paymentSem = new Semaphore(5);
  async getOrder(id: string): Promise<Order> {
    const [, release] = await this.orderSem.acquire();
    try { return await http.get(`/orders/${id}`); }
    finally { release(); }
  }
  async processPayment(data: PaymentData): Promise<Receipt> {
    const [, release] = await this.paymentSem.acquire();
    try { return await http.post('/payments', data); }
    finally { release(); }
  }
}

